css:
/* Sun State yellow is a fill colour: on light surfaces, eyebrows and text links use the darker accent so they pass AA. */
.bz-section:not(.bz-section--bg-ink):not(.bz-section--bg-accent) .bz-eyebrow{color:var(--accent-dark)}
.bz-section--bg-ink .bz-eyebrow,.bz-col--bg-ink .bz-eyebrow{color:var(--accent)}
.bz-section:not(.bz-section--bg-ink) .bz-btn--link{color:var(--accent-dark)}
.bz-block h1,.bz-block h2{text-transform:uppercase;letter-spacing:.01em}
.bz-post img{width:100%;aspect-ratio:3/2;object-fit:cover}
.bz-col--bg-card{color:var(--ink)}
